 async function toggleFeature(uid:string,feature:string,enabled:boolean){setMsg('');const {error}=await browserClient().rpc('set_employee_feature',{p_org:orgId,p_user:uid,p_feature:feature,p_enabled:enabled});if(error){setMsg(error.message);return}setFeatureAccess(old=>[...old.filter(x=>!(x.user_id===uid&&x.feature===feature)),{org_id:orgId,user_id:uid,feature,enabled}]);setMsg('Доступ сохранён')};
 async function changeWorkerStatus(person:User, next:'active'|'archived'){
  if(person.role==='admin'){setMsg('Администраторов нельзя архивировать');return}
  const question=next==='archived'
   ? `Переместить сотрудника «${person.display_name}» в архив? Его доступ к StandEL Time будет заблокирован, а история останется.`
   : `Восстановить сотрудника «${person.display_name}» и разрешить ему доступ к StandEL Time?`;
  if(!confirm(question))return;
  const {error}=await browserClient().rpc('admin_set_worker_status',{p_org:orgId,p_user:person.user_id,p_status:next});
  if(error){setMsg('Не удалось изменить статус: '+error.message);return}
  setStaff(old=>old.map(x=>x.user_id===person.user_id?{...x,status:next}:x.status==='active'&&next==='archived'&&x.supervisor_id===person.user_id?{...x,supervisor_id:null}:x));
  setMsg(next==='archived'?'Сотрудник перемещён в архив. Часы и документы сохранены.':'Сотрудник восстановлен.');
 }
 async function deleteWorker(person:User){
  if(person.role==='admin'||person.status!=='archived'){setMsg('Удалять можно только архивных работников (не администраторов)');return}
  const typed=prompt(`Безвозвратно убрать «${person.display_name}» из StandEL AB?\nЭто доступно только для архивной записи без связанных данных.\nДля подтверждения введи УДАЛИТЬ:`);
  if(typed!=='УДАЛИТЬ')return;
  const {error}=await browserClient().rpc('admin_delete_empty_worker',{p_org:orgId,p_user:person.user_id});
  if(error){setMsg('Удаление запрещено: '+error.message);return}
  setStaff(old=>old.filter(x=>x.user_id!==person.user_id));
  setMsg('Сотрудник удалён из организации. Учётная запись Supabase Auth не удалена.');
 }
