 async function changeSupervisor(uid:string,foremanId:string){const {error}=await browserClient().rpc('set_employee_supervisor',{p_org:orgId,p_user:uid,p_foreman:foremanId||null});if(error){setMsg(error.message);return}setStaff(old=>old.map(x=>x.user_id===uid?{...x,supervisor_id:foremanId||null}:x));setMsg('Бригадир назначен')};
