 const hoursPeriodLabel=hoursPeriod==='week'?`v.${isoWeekNumber(new Date(hoursWeekStart+'T12:00:00Z'))} / ${isoWeekYear(hoursWeekStart)} (${hoursWeekStart} — ${hoursWeekEnd})`:month;
 const hoursDayRecords=hoursScopedEntries.filter(e=>e.work_date===hoursSelectedDay);
 const hoursDays=Array.from({length:7},(_,i)=>{const d=new Date(hoursWeekStart+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10)});
  const filtered=entries.filter(e=>e.work_date>=from&&e.work_date<=to&&(filter==='all'||e.user_id===filter));
 const total=filtered.reduce((s,e)=>s+Number(e.hours),0);
